class Solution:
    def getKth(self, lo: int, hi: int, k: int) -> int:
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def power(n):
            if n == 1:
                return 0
            if n % 2 == 0:
                return 1 + power(n // 2)
            else:
                return 1 + power(n * 3 + 1)

        arr = [(power(i), i) for i in range(lo, hi + 1)]
        arr.sort()  # sorts by power value, then by value
        return arr[k - 1][1]
